Add-Type -AssemblyName UIAutomationClient; Add-Type -AssemblyName UIAutomationTypes; $root = [System.Windows.Automation.AutomationElement]::RootElement; $cond = [System.Windows.Automation.Condition]::TrueCondition; $wins = $root.FindAll([System.Windows.Automation.TreeScope]::Children, $cond); foreach ($w in $wins) { $n = $w.Current.Name; $c = $w.Current.ClassName; $p = $w.Current.ProcessId; if ($n -and $n.Trim()) { Write-Output "$n | $c | PID:$p" } }
